namespace axenox\Deployer\Tests\PHPUnit\Unit;

use axenox\Deployer\Common\Pipelines\NativeBuildFiles;
use axenox\Deployer\Common\Pipelines\NativeDeploymentPackage;
use axenox\Deployer\Common\Pipelines\NativeOtaPackage;
use axenox\Deployer\Common\Pipelines\PreparedDeploymentResult;
use axenox\Deployer\Common\Pipelines\ReleaseDeploymentTask;
use axenox\Deployer\Tests\PHPUnit\Fixtures\NativeTestWorkspace;
use PHPUnit\Framework\TestCase;

/**
 * Verifies historical exports without substituting them for immutable attempt storage.
 */
class NativeBuildExportTest extends TestCase
{
    /**
     * Replacing the readable copy must not alter an earlier attempt or let its cleanup delete the new copy.
     *
     * @return void
     */
    public function testRepeatedExportsRetainImmutableAttemptsAndProtectTheLatestCopy(): void
    {
        $root = NativeTestWorkspace::create('build-export');
        try {
            mkdir($root . DIRECTORY_SEPARATOR . 'builds');
            $private = $root . DIRECTORY_SEPARATOR . '.native-deployments';
            NativeDeploymentPackage::protect($private);
            $results = [];
            foreach (['first', 'second'] as $attempt) {
                $source = NativeOtaPackage::path($root, $attempt);
                file_put_contents($source, $attempt);
                $task = new ReleaseDeploymentTask($attempt, 'host', 'build', '1.2.3+fixture', $root, 'My_Local_Dev_One');
                $results[] = NativeOtaPackage::exportBuildCopy($task,
                    new PreparedDeploymentResult($source, hash_file('sha256', $source), 'fixture'));
            }
            $export = $root . DIRECTORY_SEPARATOR . 'builds' . DIRECTORY_SEPARATOR . '1.2.3+fixture_My_Local_Dev_One.phx';
            self::assertSame($export, $results[1]->artifactPath);
            self::assertSame('second', file_get_contents($export));
            self::assertSame('first', file_get_contents(NativeOtaPackage::path($root, 'first')));
            $results[0]->discard();
            self::assertSame('second', file_get_contents($export));
            self::assertFileExists(NativeOtaPackage::path($root, 'second'));
            self::assertFileDoesNotExist(dirname($export) . DIRECTORY_SEPARATOR . '.htaccess');
            self::assertFileDoesNotExist(dirname($export) . DIRECTORY_SEPARATOR . 'web.config');
            self::assertSame("Require all denied\n", file_get_contents($private . DIRECTORY_SEPARATOR . '.htaccess'));
            $results[1]->discard();
            self::assertFileDoesNotExist($export);
            self::assertFileDoesNotExist(NativeOtaPackage::path($root, 'second'));
            self::assertSame([], glob($private . DIRECTORY_SEPARATOR . '.export-*'));
        } finally {
            NativeBuildFiles::remove($root);
        }
    }

    /**
     * Existing operator server configuration must not be silently overwritten.
     *
     * @return void
     */
    public function testDisabledGenerationLeavesExistingServerRulesUntouched(): void
    {
        $root = NativeTestWorkspace::create('build-export-rules');
        try {
            $rules = $root . DIRECTORY_SEPARATOR . '.htaccess';
            file_put_contents($rules, 'operator configuration');
            NativeDeploymentPackage::protect($root, true);
            self::assertSame('operator configuration', file_get_contents($rules));
            self::assertFileDoesNotExist($root . DIRECTORY_SEPARATOR . 'web.config');
        } finally {
            NativeBuildFiles::remove($root);
        }
    }
}
